using Microsoft.Extensions.Hosting;
using Rpc.Core;
using Sample.Contracts;
using Sample.Contracts.Generated;

namespace Sample.Server.Api;

public sealed class DispatcherStartup(
    IDispatcherRegistry dispatchers,
    ProxyRegistry proxies,
    IOrderService orderService) : IHostedService
{
    public Task StartAsync(CancellationToken cancellationToken)
    {
        // Generated by Rpc.SourceGen — registra os 4 proxies do Sample.Contracts numa chamada.
        proxies.AddAllSampleContractsProxies();

        // Dispatcher só pro contrato que tem implementação local (IOrderService).
        // Os outros (IPosTerminal, IPrinterService, ITefService) vivem em agentes remotos.
        dispatchers.AddOrderServiceDispatcher(orderService);

        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
